const $=s=>document.querySelector(s);
const templates=[{id:'neon',name:'Neon editorial',theme:'neon',format:'9:16',tag:'GAMING / CULTURA',headline:'FORA DO\nÓBVIO.',description:'Contraste que prende o olhar'},{id:'lilac',name:'Recorte criativo',theme:'lilac',format:'1:1',tag:'IDEIAS / DESCOBERTAS',headline:'OUTRO\nPONTO DE VISTA.',description:'Uma nova leitura do seu conteúdo'},{id:'rose',name:'Em movimento',theme:'rose',format:'4:5',tag:'HISTÓRIAS / LIFESTYLE',headline:'DÊ PLAY\nNA SUA IDEIA.',description:'Espaço para contar sua história'}];
const key='viceclipz.projects.v1';let projects=[],currentId=null,objectUrl=null,variants=[];
try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(saved))throw Error();projects=saved.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&typeof p.headline==='string'&&templates.some(t=>t.id===p.template)&&['9:16','1:1','4:5'].includes(p.format)).map(p=>({...p,variants:Array.isArray(p.variants)?p.variants.filter(v=>typeof v==='string'):[],date:typeof p.date==='string'?p.date:''}));}catch{showToast('O armazenamento local não está disponível ou contém dados inválidos.');}
function showToast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function templateCard(t){const b=document.createElement('button');b.className='template-card';b.setAttribute('aria-label',`Usar template ${t.name}`);b.innerHTML=`<div class="template-art ${t.theme}"><span>${t.tag}</span><i></i><strong>${t.headline.replaceAll('\n','<br>')}</strong></div><div class="template-info"><div><h3>${t.name}</h3><small>${t.description}</small></div><span>${t.format}</span></div>`;b.onclick=()=>openEditor(null,t.id);return b;}
function renderTemplates(filter='all'){for(const [target,list] of [['#featured-templates',templates],['#all-templates',templates.filter(t=>filter==='all'||t.format===filter)]]){$(target).replaceChildren(...list.map(templateCard));}}
function empty(target,title,message){const el=document.createElement('div');el.className='empty';el.innerHTML='<span>▱</span><div><h3></h3><p></p></div><button class="secondary">＋ Criar projeto</button>';el.querySelector('h3').textContent=title;el.querySelector('p').textContent=message;el.querySelector('button').onclick=()=>openEditor();target.append(el);}
function renderList(target,list,type){target.replaceChildren();if(!list.length){empty(target,type==='calendar'?'Sua próxima publicação começa com um plano.':type==='search'?'Nenhum projeto encontrado.':'Uma página em branco. Infinitas ideias.',type==='calendar'?'Adicione uma data ao criar ou editar um projeto.':type==='search'?'Experimente outro nome ou crie um projeto.':'Crie seu primeiro projeto e encontre seu próximo formato.');return;}for(const p of list){const t=templates.find(t=>t.id===p.template);const el=document.createElement('article');el.className='project-row';el.innerHTML=`<span class="project-icon ${t.theme}">▹</span><div><h3></h3><small></small></div><span class="draft">Rascunho local</span><button class="secondary">Abrir ↗</button>`;el.querySelector('h3').textContent=p.name;el.querySelector('small').textContent=`${t.name} · ${p.format} · ${p.date?new Date(p.date+'T12:00:00').toLocaleDateString('pt-BR'):'Sem data planejada'}`;el.querySelector('button').onclick=()=>openEditor(p);target.append(el);}}
function render(){const query=$('#search').value.toLocaleLowerCase('pt-BR');renderList($('#recent-projects'),projects.slice(0,3));renderList($('#all-projects'),projects.filter(p=>p.name.toLocaleLowerCase('pt-BR').includes(query)),query?'search':'');renderList($('#calendar-list'),projects.filter(p=>p.date).sort((a,b)=>a.date.localeCompare(b.date)),'calendar');$('#project-count').textContent=projects.length;$('#stat-projects').textContent=projects.length;$('#stat-variants').textContent=projects.reduce((sum,p)=>sum+p.variants.length,0);}
function route(){const page=['overview','projects','templates','calendar'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==page);document.querySelectorAll('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===page);if(el.dataset.nav===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#breadcrumb').textContent={overview:'Visão geral',projects:'Meus projetos',templates:'Templates',calendar:'Calendário'}[page];}
function clearVideo(){const video=$('#video-preview');video.pause();video.removeAttribute('src');video.load();video.hidden=true;if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=null;}
function openEditor(p=null,templateId='neon'){currentId=p?.id||null;$('#project-form').reset();clearVideo();$('#form-status').textContent='';$('#editor-heading').textContent=p?'Editar projeto':'Novo projeto';$('#project-name').value=p?.name||'';$('#headline').value=p?.headline||'Uma nova perspectiva.';$('#template-select').value=p?.template||templateId;$('#format').value=p?.format||templates.find(t=>t.id===templateId).format;$('#planned-date').value=p?.date||'';variants=[...(p?.variants||[])];renderVariants();updatePreview();$('#editor').showModal();$('#project-name').focus();}
function updatePreview(){$('#preview-headline').textContent=$('#headline').value||'Sua headline aqui.';$('#composition').className='composition '+$('#template-select').value;$('#composition').style.aspectRatio=$('#format').value.replace(':','/');$('#preview-format').textContent=$('#format').value;}
function renderVariants(){const target=$('#variants');target.replaceChildren();if(variants.length){const note=document.createElement('p');note.textContent='Sugestões por regras locais, sem IA. Clique para aplicar.';target.append(note);}for(const headline of variants){const btn=document.createElement('button');btn.type='button';btn.textContent=headline;btn.onclick=()=>{$('#headline').value=headline;updatePreview();};target.append(btn);}}
for(const t of templates){const opt=document.createElement('option');opt.value=t.id;opt.textContent=t.name;$('#template-select').append(opt);}
document.querySelectorAll('.new-project').forEach(b=>b.onclick=()=>openEditor());$('#close-editor').onclick=()=>$('#editor').close();$('#editor').addEventListener('close',clearVideo);$('#headline').addEventListener('input',updatePreview);$('#format').addEventListener('change',updatePreview);$('#template-select').addEventListener('change',updatePreview);$('#search').addEventListener('input',render);
$('#video-file').addEventListener('change',()=>{clearVideo();const file=$('#video-file').files[0];if(!file)return;if(!file.type.startsWith('video/')||file.size>100*1024*1024){$('#form-status').textContent='Escolha um vídeo válido de até 100 MB.';$('#video-file').value='';return;}$('#form-status').textContent='';objectUrl=URL.createObjectURL(file);$('#video-preview').src=objectUrl;$('#video-preview').hidden=false;});$('#video-preview').addEventListener('error',()=>{$('#form-status').textContent='Este formato de vídeo não pôde ser reproduzido. Tente MP4 ou WebM.';clearVideo();});
$('#generate').onclick=()=>{const base=$('#headline').value.trim().replace(/[.!?]+$/,'').slice(0,65);if(!base){$('#form-status').textContent='Escreva uma headline para explorar variações.';return;}$('#form-status').textContent='';variants=[`${base}. Um novo olhar.`,`Você já reparou? ${base}`,`${base}: veja os detalhes.`];renderVariants();};
$('#project-form').addEventListener('submit',event=>{event.preventDefault();const name=$('#project-name').value.trim(),headline=$('#headline').value.trim();if(!name||!headline){$('#form-status').textContent='Preencha o nome e a headline do projeto.';return;}const p={id:currentId||crypto.randomUUID(),name,headline,template:$('#template-select').value,format:$('#format').value,date:$('#planned-date').value,variants,updatedAt:new Date().toISOString()};const next=[p,...projects.filter(item=>item.id!==p.id)];try{localStorage.setItem(key,JSON.stringify(next));projects=next;render();$('#editor').close();showToast('Projeto salvo neste navegador. Vamos criar?');}catch{$('#form-status').textContent='Não foi possível salvar. Verifique o espaço e as permissões do navegador.';}});
document.querySelectorAll('[data-filter]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn));});renderTemplates(btn.dataset.filter);});window.addEventListener('hashchange',route);renderTemplates();render();route();
